/**
 * @param string $name  $ICON_PATHS 키 (예: 'mail', 'ruler')
 * @param array  $opts  ['class' => '추가 CSS 클래스', 'size' => 픽셀 크기(기본 CSS로 제어하려면 생략)]
 */
function icon(string $name, array $opts = []): string
{
    global $ICON_PATHS;
    $inner = $ICON_PATHS[$name] ?? null;
    if ($inner === null) {
        return ''; // 모르는 이름이면 조용히 빈 값 (레이아웃 안 깨지게)
    }
    $class = 'icon' . (!empty($opts['class']) ? ' ' . $opts['class'] : '');
    $sizeAttr = !empty($opts['size']) ? ' style="width:' . (int) $opts['size'] . 'px;height:' . (int) $opts['size'] . 'px;"' : '';
    return '<svg class="' . htmlspecialchars($class) . '" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"' . $sizeAttr . '>' . $inner . '</svg>';
}
